"""Keep the metadata-only distribution aligned with core's version and extras.

Run before locking/building after a version bump. CI uses --check to detect drift.
"""

import argparse
from pathlib import Path
import tomllib

ROOT = Path(__file__).resolve().parents[1]


def render(project: dict) -> str:
    version = project["version"]
    extras = project["optional-dependencies"]
    lines = [
        "# Generated by scripts/sync_convenience.py; edit core's pyproject.toml instead.",
        "[project]",
        'name = "altk-evolve"',
        f'version = "{version}"',
        'description = "Agent memory with server, CLI, FastEmbed and tracing included"',
        'readme = "README.md"',
        f'requires-python = "{project["requires-python"]}"',
        f'dependencies = ["altk-evolve-core[server,cli,fastembed,tracing]=={version}"]',
        "",
        "[project.optional-dependencies]",
        *[f'{extra} = ["altk-evolve-core[{extra}]=={version}"]' for extra in extras],
        "",
        "[build-system]",
        'requires = ["setuptools>=77"]',
        'build-backend = "setuptools.build_meta"',
        "",
        "[tool.setuptools]",
        "packages = []",
        "",
    ]
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    project = tomllib.loads((ROOT / "pyproject.toml").read_text())["project"]
    target = ROOT / "packages/altk-evolve/pyproject.toml"
    expected = render(project)
    if args.check:
        if not target.exists() or target.read_text() != expected:
            raise SystemExit("Convenience metadata is stale; run uv run --no-project python scripts/sync_convenience.py")
    else:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(expected)


if __name__ == "__main__":
    main()
